"""Put every ticker on one calendar (DATA-03, DATA-04)."""

from collections.abc import Mapping, Sequence

from mdata.types import GapError, Prices, RawRow


def align_calendar(rows: Sequence[RawRow], *, max_gap: int = 5) -> Prices:
    """One calendar from the first date every ticker has a close; gaps take the previous close."""
    by_ticker: dict[str, dict[str, float]] = {}
    for row in rows:
        closes = by_ticker.setdefault(row.ticker, {})
        if row.close is not None:
            closes[row.date] = row.close
    tickers = tuple(sorted(by_ticker))
    start = max(min(closes, default="") for closes in by_ticker.values())
    traded = set().union(*(closes.keys() for closes in by_ticker.values()))
    dates = tuple(sorted(d for d in traded if d >= start))
    return Prices(
        dates=dates,
        tickers=tickers,
        closes={t: _fill(t, by_ticker[t], dates, max_gap) for t in tickers},
    )


def _fill(
    ticker: str, closes: Mapping[str, float], dates: Sequence[str], max_gap: int
) -> tuple[float, ...]:
    """The ticker's close on each date, a missing date taking the previous close."""
    filled: list[float] = []
    missing = 0
    for date in dates:
        if date in closes:
            filled.append(closes[date])
            missing = 0
            continue
        missing += 1
        if missing > max_gap:
            msg = f"{ticker} misses more than {max_gap} dates in a row before {date}"
            raise GapError(msg)
        filled.append(filled[-1])
    return filled and tuple(filled) or ()

